INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 40 anos, proveniente de área rural da Ásia e residente no Brasil há 2 anos, apresenta-se com tosse crônica, hemoptise leve e dor torácica. A radiografia revela derrame pleural à direita e infiltrado pulmonar migratório. A análise do líquido pleural mostra um exsudato com 55% de eosinófilos, glicose de 15 mg/dL e LDH de 1.500 U/L. Qual o agente etiológico mais provável considerando a epidemiologia e o perfil bioquímico ''explosivo'' do líquido?", "options": {"a": "Schistosoma mansoni.", "b": "Paragonimus westermani.", "c": "Strongyloides stercoralis.", "d": "Toxocara canis (Larva Migrans Visceral).", "e": "Ancylostoma duodenale."}, "answer": "b", "rationale": "A paragonimíase (distomatose pulmonar) é uma causa clássica de derrame pleural eosinofílico que, paradoxalmente, apresenta bioquímica de empiema ou artrite reumatoide: glicose baixíssima (< 20 mg/dL) e LDH muito elevado. O contexto de paciente asiático com sintomas pleuropulmonares crônicos é altamente sugestivo.", "option_rationales": {"a": "Incorreta. O Schistosoma causa mais hipertensão pulmonar do que derrame eosinofílico com glicose baixa.", "b": "Correta. Perfil bioquímico patognomônico em contexto epidemiológico favorável.", "c": "Incorreta. Estrongiloidíase disseminada causa pneumonia e SDRA, mas não derrame com este padrão bioquímico.", "d": "Incorreta. Causa eosinofilia periférica marcada, mas o derrame eosinofílico costuma ter glicose normal.", "e": "Incorreta. Não apresenta tropismo pleural para causar exsudatos tão agressivos."}, "difficulty": "dificil", "tags": ["Pneumologia", "Infectologia", "Parasitoses", "Eosinofilia Pleural"]}'::jsonb, 100, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A Pleurite Bacteriana Espontânea (SBPE) é uma complicação da cirrose hepática com hidrotórax hepático. Qual o critério diagnóstico para SBPE na análise do líquido pleural?", "options": {"a": "Presença de pus franco no espaço pleural.", "b": "Contagem de Polimorfonucleares (PMN) > 250 células/mm³ com cultura positiva ou PMN > 500 células/mm³ se a cultura for negativa (excluindo empiema de causa pulmonar).", "c": "Proteína total pleural > 3,0 g/dL.", "d": "pH pleural < 7,10 em todas as amostras.", "e": "Dosagem de amilase pleural 3x maior que a sérica."}, "answer": "b", "rationale": "A SBPE é o equivalente pleural da Peritonite Bacteriana Espontânea (PBE). Ocorre em pacientes cirróticos com hidrotórax preexistente. O diagnóstico é baseado na celularidade (PMN > 250 ou 500) e na exclusão de um foco infeccioso pulmonar (pneumonia) adjacente, que caracterizaria um derrame parapneumônico e não SBPE.", "option_rationales": {"a": "Incorreta. Pus franco indica empiema estabelecido, não a forma ''espontânea'' do cirrótico.", "b": "Correta. Critério análogo ao da PBE adaptado para a pleura.", "c": "Incorreta. O hidrotórax hepático é classicamente transudato (proteína baixa).", "d": "Incorreta. O pH pode não atingir valores tão baixos na fase inicial.", "e": "Incorreta. Amilase alta indica causa pancreática ou ruptura esofágica."}, "difficulty": "dificil", "tags": ["Pneumologia", "Gastroenterologia", "Cirrose", "SBPE"]}'::jsonb, 101, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico de Mesotelioma Maligno por citologia ou biópsia, a imuno-histoquímica é fundamental. Quais marcadores são tipicamente POSITIVOS no mesotelioma e ajudam a excluí-lo de um Adenocarcinoma metastático?", "options": {"a": "CEA e Ber-EP4.", "b": "TTF-1 e Napsina A.", "c": "Calretinina, WT1 e Citoqueratina 5/6.", "d": "CD20 e CD30.", "e": "Proteína S100 e HMB-45."}, "answer": "c", "rationale": "A calretinina, o WT1 (Wilms Tumor 1) e a citoqueratina 5/6 são os marcadores mesoteliais clássicos. Se presentes, confirmam a origem mesotelial da célula. O CEA, Ber-EP4, TTF-1 e Napsina A são marcadores clássicos de epitélio pulmonar/adenocarcinoma (negativos no mesotelioma).", "option_rationales": {"a": "Incorreta. Positivos no adenocarcinoma.", "b": "Incorreta. Positivos no câncer de pulmão primário.", "c": "Correta. Painel imuno-histoquímico padrão para mesotelioma.", "d": "Incorreta. Marcadores de linfoma.", "e": "Incorreta. Marcadores de melanoma."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Mesotelioma", "Imuno-histoquímica"]}'::jsonb, 102, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente feminina, 32 anos, apresenta episódios recorrentes de pneumotórax e derrame pleural quiloso (Quilotórax). A tomografia de tórax revela múltiplos cistos aéreos de paredes finas distribuídos difusamente pelo parênquima pulmonar. Qual o diagnóstico mais provável?", "options": {"a": "Histiocitose de Células de Langerhans.", "b": "Linfangioleiomiomatose (LAM).", "c": "Fibrose Cística.", "d": "Enfisema pan-acinar por deficiência de alfa-1 antitripsina.", "e": "Pneumonia Intersticial Linfocítica."}, "answer": "b", "rationale": "A LAM é uma doença rara que acomete quase exclusivamente mulheres em idade fértil. Caracteriza-se pela proliferação de células musculares lisas atípicas (células LAM) que obstruem vias aéreas (causando cistos/pneumotórax) e vasos linfáticos (causando quilotórax).", "option_rationales": {"a": "Incorreta. Causa pneumotórax e cistos (especialmente em ápices e tabagistas), mas não quilotórax.", "b": "Correta. Associação clássica: mulher jovem + cistos + quilotórax.", "c": "Incorreta. Doença bronquiolar supurativa crônica, não cística/quilotórax primário.", "d": "Incorreta. Enfisema não cursa com quilotórax.", "e": "Incorreta. Associada a doenças autoimunes (Sjögren), mas o quilotórax não é típico."}, "difficulty": "media", "tags": ["Pneumologia", "LAM", "Quilotórax", "Mulher"]}'::jsonb, 103, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No manejo do Quilotórax Refratário ao tratamento conservador (dieta com TCM, octreotide), em um paciente com insuficiência cardíaca grave ou cirrose, uma opção de tratamento avançado que reduz a pressão no sistema linfático através da descompressão biliar/portal é:", "options": {"a": "Transplante de pulmão.", "b": "TIPS (Shunt Portossistêmico Intra-hepático Transjugular).", "c": "Pleurectomia parietal radical.", "d": "Ligadura do ducto torácico via cervical.", "e": "Criação de fístula arteriovenosa no braço."}, "answer": "b", "rationale": "Em casos de quilotórax ou hidrotórax hepático secundários à hipertensão portal ou pressões venosas centrais elevadas, o TIPS pode reduzir a produção de linfa e favorecer a resolução do derrame por melhorar a dinâmica hemodinâmica sistêmica e esplâncnica.", "option_rationales": {"a": "Incorreta. Conduta extrema não indicada para quilotórax isolado.", "b": "Correta. Opção terapêutica para casos cirrogênicos/hemodinâmicos refratários.", "c": "Incorreta. Procedimento de alto risco em pacientes com IC/Cirrose.", "d": "Incorreta. O ducto deve ser ligado no tórax, não na cervical, para a maioria dos derrames pleurais.", "e": "Incorreta. Aumentaria a sobrecarga cardíaca."}, "difficulty": "dificil", "tags": ["Pneumologia", "Gastroenterologia", "Terapêutica Avançada", "Quilotórax"]}'::jsonb, 104, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A medição do LDH pleural é fundamental nos critérios de Light. Em qual situação a dosagem de isoenzimas do LDH (LDH-1 a LDH-5) pode ter utilidade clínica?", "options": {"a": "Para confirmar Tuberculose Pleural.", "b": "Para diferenciar derrame neoplásico de empiema (LDH-4 e LDH-5 elevados no empiema/processos agudos).", "c": "Identificar quilotórax traumático.", "d": "Somente em exames veterinários.", "e": "Em derrames transudativos para prever resposta a diuréticos."}, "answer": "b", "rationale": "Embora raramente usadas, as isoenzimas do LDH refletem a origem da agressão tecidual. LDH-4 e LDH-5 (típicos de granulócitos) estão muito elevados em empiemas e processos inflamatórios agudos. No câncer, o padrão de isoenzimas costuma ser mais difuso ou com predomínio de LDH-2 e LDH-3.", "option_rationales": {"a": "Incorreta. Não tem valor específico na TB.", "b": "Correta. Ajuda a distinguir a fonte da inflamação celular no líquido.", "c": "Incorreta. Quilotórax tem LDH baixo.", "d": "Incorreta. Afirmação sem fundamento.", "e": "Incorreta. Transudatos têm LDH baixo, sem valor nas isoenzimas."}, "difficulty": "dificil", "tags": ["Pneumologia", "Laboratório", "Bioquímica", "LDH"]}'::jsonb, 105, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista crônico e etilista é diagnosticado com câncer de esôfago médio. Ele desenvolve derrame pleural volumoso à direita, de aspecto purulento, com pH 6,8. No líquido, observa-se a presença de partículas de alimentos e amilase pleural de 15.000 U/L. Qual a conduta cirúrgica MAIS URGENTE?", "options": {"a": "Drenagem pleural tubular e antibioticoterapia venosa apenas.", "b": "Mediastinostomia cervical para drenagem de abscesso.", "c": "Toracocinese de alívio seguida de endoscopia digestiva diagnóstica.", "d": "Esofagectomia de emergência ou exclusão esofágica com drenagem mediastinal e pleural ampla.", "e": "Gastrostomia para alimentação."}, "answer": "d", "rationale": "A presença de partículas de alimento no líquido pleural confirma ruptura esofágica (Síndrome de Boerhaave ou perfuração neoplásica). Trata-se de uma emergência cirúrgica catastrófica com mediastinite química e bacteriana severa. O tratamento exige controle imediato da fístula e drenagem agressiva de todos os compartimentos contaminados.", "option_rationales": {"a": "Incorreta. Insuficiente diante de uma fístula digestiva contínua.", "b": "Incorreta. A perfuração é torácica (esôfago médio), a mediastinostomia cervical não alcança o foco adequadamente.", "c": "Incorreta. Procedimento diagnóstico puramente, a urgência é terapêutica.", "d": "Correta. Conduta de salvação para ruptura esofágica com contaminação pleural.", "e": "Incorreta. Medida de suporte que não resolve a infecção pleural/mediastinal ativa."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Torácica", "Esofagostomia", "Mediastinite"]}'::jsonb, 106, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "O ''Pseudoquilotórax'' (Derrame de Colesterol) é caracterizado pelo acúmulo de cristais de colesterol no espaço pleural. Diferente do quilotórax, quais doenças estão classicamente associadas a esse quadro crônico?", "options": {"a": "Trauma torácico e Cirurgia Cardíaca.", "b": "Artrite Reumatoide e Tuberculose de longa data.", "c": "Linfoma e Carcinoma de Mama.", "d": "Insuficiência Cardíaca e Síndrome Nefrótica.", "e": "Pneumonia Estafilocócica e HIV."}, "answer": "b", "rationale": "O pseudoquilotórax ocorre em processos pleurais crônicos onde o espessamento das pleuras impede a absorção dos lipídios provenientes da quebra de células inflamatórias e hemácias. TB de longa data (antes tratada apenas com colapsoterapia) e Artrite Reumatoide crônica são as causas clássicas.", "option_rationales": {"a": "Incorreta. Causas de quilotórax agudo.", "b": "Correta. Padrão clínico de doenças inflamatórias crônicas da pleura.", "c": "Incorreta. Neoplasias causam mais quilotórax (por obstrução do ducto) que pseudo.", "d": "Incorreta. Causas de transudato.", "e": "Incorreta. Não associadas à cronicidade necessária para acumular cristais de colesterol."}, "difficulty": "media", "tags": ["Pneumologia", "Bioquímica", "Colesterol", "Pseudochylothorax"]}'::jsonb, 107, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Ao avaliar uma tomografia de tórax de um paciente com dor torácica incaracterística, percebe-se um espessamento isolado da pleura mediastinal à esquerda. Qual a significância deste achado radiológico?", "options": {"a": "Sempre indica neoplasia agressiva.", "b": "É um achado inespecífico, frequentemente relacionado a gordura epicárdica ou mediastinal exuberante.", "c": "Sinal patognomônico de asbestose.", "d": "Indica perfuração de brônquio fonte.", "e": "Sugerido como local de biópsia para amiloidose."}, "answer": "b", "rationale": "O ''espessamento'' pleural na região mediastinal ou paravertebral é frequentemente simulado pelo acúmulo de gordura extrapleural. É um achado comum e geralmente benigno, a menos que seja nodular ou associado a derrame pleural ou massas mediastinais reais.", "option_rationales": {"a": "Incorreta. O diagnóstico mais comum é lipomatose mediastinal/extrapleural.", "b": "Correta. Pista radiológica para evitar pânico diagnóstico.", "c": "Incorreta. Asbestose atinge a pleura parietal lateral e o diafragma, não a mediastinal isolada.", "d": "Incorreta. Perfuração brônquica causaria pneumomediastino rápido.", "e": "Incorreta. Amiloidose pleural é rara e não se baseia nesse achado isolado."}, "difficulty": "media", "tags": ["Pneumologia", "Radiologia", "Anatomia", "Variantes"]}'::jsonb, 108, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em pacientes com infecção pelo vírus HIV, a ocorrência de derrame pleural por Sarcoma de Kaposi apresenta qual característica do líquido?", "options": {"a": "Transudato amarelo citrino.", "b": "Exsudato tipicamente hemorrágico, com citologia frequentemente negativa para células malignas claras.", "c": "Líquido leitoso rico em linfócitos CD4.", "d": "Pus franco com bactérias intracelulares.", "e": "Líquido viscoso tipo ''gelatina de morango'' (ácido hialurônico elevado)."}, "answer": "b", "rationale": "O envolvimento pleural pelo Sarcoma de Kaposi no HIV é uma causa de derrame exsudativo e hemorrágico. O diagnóstico citológico é difícil porque as células fusiformes do sarcoma não se soltam facilmente para o líquido, muitas vezes exigindo biópsia ou visualização direta por VATS (lesões violáceas na pleura).", "option_rationales": {"a": "Incorreta. Tumores causam exsudatos.", "b": "Correta. Perfil do Kaposi visceral no tórax.", "c": "Incorreta. O quilotórax no HIV pode ocorrer por linfoma, mas o Kaposi é hemorrágico.", "d": "Incorreta. Isso seria um empiema.", "e": "Incorreta. Descrição clássica do mesotelioma rico em ácido hialurônico."}, "difficulty": "dificil", "tags": ["Pneumologia", "Infectologia", "HIV/AIDS", "Sarcoma de Kaposi"]}'::jsonb, 109, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal causa de morte por complicações do procedimento de toracentese de grande volume (> 1,5 L)?", "options": {"a": "Pneumotórax hipertensivo.", "b": "Edema Pulmonar de Reexpansão (EPR).", "c": "Embolia gasosa coronariana.", "d": "Síncope vasovagal com parada em assistolia.", "e": "Hemorragia por laceração da artéria intercostal."}, "answer": "b", "rationale": "O edema pulmonar de reexpansão é a complicação mais temida em toracocenteses ou drenagens volumosas. Ocorre por danos causados por radicais livres durante a reoxigenação rápida do pulmão previamente colapsado e mudanças bruscas na pressão hidrostática. Pode levar à falência respiratória grave e choque.", "option_rationales": {"a": "Incorreta. Grave, mas tratável com drenagem imediata.", "b": "Correta. Complicação sistêmica grave por agressão endotelial pós-reexpansão.", "c": "Incorreta. Rara e imediata ao acidente de punção.", "d": "Incorreta. Frequentemente benigna se manejada com posição.", "e": "Incorreta. Grave, mas cirurgicamente controlável."}, "difficulty": "media", "tags": ["Pneumologia", "Procedimentos", "EPR", "Complicações"]}'::jsonb, 110, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A fístula pleuroperitoneal em pacientes com ascite por cirrose Child-Pugh C geralmente leva a um hidrotórax localizado em qual hemitórax?", "options": {"a": "Esquerdo em 90% dos casos.", "b": "Bilateral em todos os casos.", "c": "Direito em cerca de 75-85% dos casos.", "d": "Apenas na base do pulmão esquerdo.", "e": "Exclusivamente mediastinal."}, "answer": "c", "rationale": "O hidrotórax hepático é predominantemente à direita. Isso ocorre porque o hemidiafragma direito é anatomicamente mais propenso a defeitos congênitos ou fendas adquiridas, e a pressão negativa intratorácica ''puxa'' a ascite do abdome para o tórax por esses trajetos.", "option_rationales": {"a": "Incorreta. Inverso da estatística real.", "b": "Incorreta. Costuma ser unilateral pela localização da fístula.", "c": "Correta. Localização preferencial anatomofisiológica.", "d": "Incorreta. Não é o padrão.", "e": "Incorreta. Não ocorre no mediastino."}, "difficulty": "facil", "tags": ["Pneumologia", "Gastroenterologia", "Hidrotórax Hepático", "Cirrose"]}'::jsonb, 111, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A presença de infiltrados pulmonares migratórios e derrame pleural com eosinofilia intensa (> 20%) em um paciente com asma grave recém-diagnosticada sugere qual vasculite sistêmica?", "options": {"a": "Granulomatose de Wegener.", "b": "Poliarterite Nodosa.", "c": "Granulomatose Eosinofílica com Poliangiite (Churg-Strauss).", "d": "Arterite de Células Gigantes.", "e": "Doença de Behçet."}, "answer": "c", "rationale": "A síndrome de Churg-Strauss é definida pela tríade: asma, eosinofilia periférica/tecidual e vasculite sistêmica. O derrame pleural exsudativo eosinofílico ocorre em cerca de 30% dos pacientes durante a fase de vasculite ativa.", "option_rationales": {"a": "Incorreta. Cursa com nódulos cavitados e granulomas, não eosinofilia marcada.", "b": "Incorreta. Não acomete o pulmão de forma clássica.", "c": "Correta. Tríade clínica clássica.", "d": "Incorreta. Vasculite de grandes vasos em idosos.", "e": "Incorreta. Afta oral, genital e uveíte; acometimento pleural é raro."}, "difficulty": "facil", "tags": ["Pneumologia", "Vasculites", "Churg-Strauss", "Asma"]}'::jsonb, 112, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em relação à ''Síndrome de Meigs'', qual dos seguintes tumores ovarianos NÃO faz parte da definição clássica (que exige tumor benigno)?", "options": {"a": "Fibroma de ovário.", "b": "Tecoma.", "c": "Tumor de Brenner.", "d": "Adenocarcinoma de Ovário.", "e": "Cistoadenoma."}, "answer": "d", "rationale": "A Síndrome de Meigs clássica exige tumor benigno de ovário + ascite + derrame pleural, com resolução dos derrames após a cirurgia. O adenocarcinoma é maligno; sua tríade ascite/derrame seria a ''Pseudo-síndrome de Meigs'' ou simplesmente carcinomatose peritoneal/pleural.", "option_rationales": {"a": "Incorreta. É o tumor mais clássico do Meigs.", "b": "Incorreta. É um tumor benigno estromal que causa a síndrome.", "c": "Incorreta. Tumor fibroepitelial benigno associado ao Meigs.", "d": "Correta. Tumor maligno que invalida a definição de Meigs puro.", "e": "Incorreta. Tumor epitelial benigno associado."}, "difficulty": "media", "tags": ["Pneumologia", "Ginecologia", "Meigs", "Tumor Ovariano"]}'::jsonb, 113, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico da etiologia do derrame pleural, o achado de células de câncer no líquido pleural em um paciente com tumor de pulmão conhecido confere qual estádio T N M?", "options": {"a": "Tis.", "b": "M1a.", "c": "T4.", "d": "M1b.", "e": "N3."}, "answer": "b", "rationale": "De acordo com o sistema TNM (8ª edição) para câncer de pulmão, a presença de nódulos pleurais ou pericárdicos malignos ou de derrames pleural/pericárdico malignos é classificada como estádio M1a (doença metastática intratorácica), conferindo automaticamente o estágio IV.", "option_rationales": {"a": "Incorreta. Carcinoma in situ.", "b": "Correta. Critério de disseminação pleural metastática intratorácica.", "c": "Incorreta. T4 seria invasão de grandes vasos ou esôfago, mas não disseminação pleural livre por células no líquido.", "d": "Incorreta. M1b é metástase extratorácica única.", "e": "Incorreta. Reflete comprometimento de linfonodos cervicais ou contralaterais."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "TNM", "Estadiamento"]}'::jsonb, 114, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A realização de ''Toracocentese repetida'' (Symphony of Thoracentesis) em pacientes com derrame neoplásico sem reexpansão pulmonar deve ser desencorajada em favor de qual conduta agressiva/definitiva?", "options": {"a": "Pneumonectomia de resgate.", "b": "Administração de quimioterapia intrapleural isolada.", "c": "Inserção de cateter pleural de demora (IPC).", "d": "Uso de doses altas de furosemida endovenosa.", "e": "Substituição do oxigênio por hélio."}, "answer": "c", "rationale": "Se o pulmão está encarcerado (não reexpande com a drenagem), a pleurodese química falhará e a toracentese repetida levará a multiloculações, empiema e desconforto crônico. O cateter de demora (IPC) permite a drenagem paliativa sem necessidade de sínfise pleural.", "option_rationales": {"a": "Incorreta. Extremamente agressivo e sem benefício paliativo em doença avançada.", "b": "Incorreta. Taxas de sucesso menores que IPC para controle de sintomas.", "c": "Correta. Melhor conduta para ''pulmão encarcerado'' sintomático.", "d": "Incorreta. Diuréticos não resolvem derrame neoplásico (exsudato).", "e": "Incorreta. Heliox não tem papel no derrame pleural."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Palhação", "Terapêutica"]}'::jsonb, 115, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 22 anos apresenta febre e derrame pleural linfocítico (88%). ADA de 45 U/L. Biópsia pleural de Abrams com granulomas e necrose de caseificação. Sobre a necessidade de isolamento respiratório para este paciente na enfermaria, assinale a correta.", "options": {"a": "Obrigatório para todos os pacientes com TB de qualquer sítio.", "b": "Desnecessário se o paciente não tiver lesão pulmonar parenquimatosa cavitária associada e se a baciloscopia de escarro for negativa.", "c": "Deve durar pelo menos 6 meses.", "d": "O dreno de tórax aumenta o risco de contágio aéreo por aerolização.", "e": "A biópsia pleural confirma que o paciente é altamente bacilífero."}, "answer": "b", "rationale": "A Tuberculose Pleural isolada não é considerada infectante, pois não há comunicação entre o espaço pleural e as vias aéreas para a produção de aerossóis bacilíferos. O isolamento só é necessário se houver Tuberculose Pulmonar concomitante (o que ocorre em cerca de 20-30% dos casos de TB pleural).", "option_rationales": {"a": "Incorreta. TB extrapulmonar isolada (ex: pleural, óssea, ganglionar) não exige precauções para aerossóis.", "b": "Correta. Regra fundamental de isolamento hospitalar.", "c": "Incorreta. O isolamento termina após 15 dias de tratamento eficaz se a TB for pulmonar infectante.", "d": "Incorreta. O dreno é um sistema fechado.", "e": "Incorreta. A biópsia reflete o tecido pleural, não a carga bacilífera nas vias aéreas respiratórias."}, "difficulty": "media", "tags": ["Pneumologia", "Infectologia", "Controle de Infecção", "Tuberculose"]}'::jsonb, 116, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurite Renal'' é uma manifestação do Lúpus Eritematoso Sistêmico (LES). Entretanto, o termo ''Derrame Pleural Urêmico'' refere-se especificamente a:", "options": {"a": "Derrame pleural por nefrose lipoídica.", "b": "Exsudato fibrinoso em pacientes com insuficiência renal avançada sem outra causa explicável.", "c": "Acúmulo de urina na pleura por ruptura de ureter (Urinotórax).", "d": "Transudato por hipoalbuminemia nefrótica.", "e": "Empiema por fístula nefropleural."}, "answer": "b", "rationale": "A pleurite urêmica ocorre em pacientes com ureia muito elevada (geralmente > 100 mg/dL). É um exsudato fibrinoso e muitas vezes hemorrágico. O tratamento é a diálise intensiva, que leva à resolução do derrame na maioria das vezes. Deve-se distinguir do urinotórax (urina na pleura).", "option_rationales": {"a": "Incorreta. Nefrose causa transudato.", "b": "Correta. Entidade inflamatória clássica da uremia severa.", "c": "Incorreta. Isso é urinotórax.", "d": "Incorreta. Isso é transudato da síndrome nefrótica.", "e": "Incorreta. Condição rara (fístula), não relacionada à síndrome urêmica metabólica."}, "difficulty": "dificil", "tags": ["Pneumologia", "Nefrologia", "Uremia", "Pleurite"]}'::jsonb, 117, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A coloração de Gram no líquido pleural tem sensibilidade moderada, mas alta especificidade. Se o Gram for positivo em um paciente com derrame parapneumônico, mas as culturas forem negativas após 72h, qual a interpretação clínica?", "options": {"a": "O Gram foi um falso-positivo por contaminação do reagente.", "b": "As bactérias estão mortas ou o crescimento foi inibido por antibióticos prévios, mas o derrame ainda deve ser tratado como empiema/complicado.", "c": "A infecção é viral.", "d": "Trata-se de Tuberculose disfarçada de bactéria.", "e": "O dreno de tórax pode ser retirado imediatamente."}, "answer": "b", "rationale": "Gram positivo = Germe visualizado. Se a cultura for negativa, isso frequentemente decorre do fato de o paciente já estar recebendo antibióticos que ''esterilizam'' a amostra mas as carcaças bacterianas ou germes não viáveis persistem. A drenagem e o tratamento agressivo continuam indicados.", "option_rationales": {"a": "Incorreta. Menos provável no cenário clínico.", "b": "Correta. Padrão comum no empiema ''descapitados'' por antibiótico.", "c": "Incorreta. Vírus não aparecem no Gram.", "d": "Incorreta. TB não aparece no Gram comum (precisa de Ziehl).", "e": "Incorreta. Se houve germe no espaço pleural, a drenagem é necessária até resolução clínica total."}, "difficulty": "facil", "tags": ["Pneumologia", "Laboratório", "Microbiologia", "Empiema"]}'::jsonb, 118, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico da etiologia do derrame pleural, o uso de biomarcadores como a Procalcitonina no líquido pleural (e não no soro) apresenta qual evidência atual?", "options": {"a": "Substitui a dosagem de pH e glicose com vantagem.", "b": "É o melhor marcador para distinguir Tuberculose de Câncer.", "c": "Possui baixa utilidade clínica comprovada, não sendo superior aos parâmetros bioquímicos tradicionais (pH, glicose, LDH).", "d": "Indica obrigatoriamente etiologia por Legionella.", "e": "É mandatório em todos os transudatos cardíacos."}, "answer": "c", "rationale": "Diferente da Procalcitonina sérica (útil na sepse), a Procalcitonina no líquido pleural tem demonstrado baixo valor agregado. Ela não diferencia de forma confiável o empiema de outros exsudatos inflamatórios melhor do que o pH ou o LDH.", "option_rationales": {"a": "Incorreta. pH e glicose permanecem superiores.", "b": "Incorreta. Sem utilidade neste diferencial.", "c": "Correta. Evidência clínica atual desencoraja o uso rotineiro do biomarcador pleural.", "d": "Incorreta. Sem relação específica.", "e": "Incorreta. Sem aplicação em transudatos."}, "difficulty": "dificil", "tags": ["Pneumologia", "Biomarcadores", "Evidência", "Procalcitonina"]}'::jsonb, 119, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 68 anos, portador de insuficiência cardíaca e doença renal crônica, apresenta-se com derrame pleural bilateral. A análise do líquido pleural revela: Proteína 2,9 g/dL (Sérica 6,0 g/dL), LDH 190 U/L (Sérico 420 U/L - limite superior do soro 450 U/L). Pelos critérios de Light, o líquido é classificado como exsudato (Prot P/S > 0,5). No entanto, a dosagem de NT-proBNP no líquido pleural é de 3.200 pg/mL. Qual a interpretação mais provável?", "options": {"a": "Derrame pleural maligno oculto.", "b": "Tuberculose pleural paucibacilar.", "c": "Derrame cardíaco rotulado como exsudato falso-positivo pelos critérios de Light (frequentemente devido ao uso de diuréticos).", "d": "Pleurite urêmica aguda.", "e": "Empiema bacteriano na fase inicial."}, "answer": "c", "rationale": "Em pacientes com ICC usando diuréticos, os critérios de Light podem falhar (especialmente a relação de proteínas). Um NT-proBNP pleural > 1.500 pg/mL tem altíssima especificidade para origem cardíaca, sendo o melhor marcador para desmentir um falso exsudato do Light nestes casos.", "option_rationales": {"a": "Incorreta. O NT-proBNP alto aponta para a via cardíaca.", "b": "Incorreta. TB teria ADA alto e não elevaria NT-proBNP.", "c": "Correta. Aplicação clássica de biomarcadores cardíacos no líquido pleural.", "d": "Incorreta. Pleurite urêmica é um exsudato real (fibrinoso/linfocítico), não explicaria o NT-proBNP tão alto sem falha cardíaca associada.", "e": "Incorreta. Empiema teria pH baixo e neutrofilia."}, "difficulty": "media", "tags": ["Pneumologia", "Bioquímica", "ICC", "NT-proBNP"]}'::jsonb, 120, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre o mecanismo de produção do líquido pleural na fisiologia normal (Ponto de vista de Starling), qual a afirmação correta de acordo com os conceitos modernos?", "options": {"a": "O líquido é produzido na pleura visceral e absorvido na pleura parietal.", "b": "O líquido é produzido principalmente pelos capilares da pleura parietal e absorvido predominantemente pelos linfáticos estomais da pleura parietal.", "c": "A pleura visceral é a principal responsável pela absorção linfática do líquido pleural no ser humano.", "d": "A pressão oncótica das proteínas no espaço pleural é zero em condições normais.", "e": "A drenagem linfática pleural não tem influência no volume do líquido."}, "answer": "b", "rationale": "Conceitos clássicos sugeriam produção na parietal e absorção na visceral. No entanto, estudos modernos mostram que no ser humano a pleura parietal (suprida pela circulação sistêmica e com maior gradiente de pressão) é responsável tanto pela maior parte da produção quanto pela quase totalidade da absorção (via linfáticos estomais da pleura parietal inferior e diafragmática).", "option_rationales": {"a": "Incorreta. Conceito antigo e anatomicamente impreciso para humanos.", "b": "Correta. Visão fisiológica contemporânea da dinâmica de fluidos pleural.", "c": "Incorreta. A pleura visceral no humano é espessa e sua drenagem linfática é voltada para o parênquima/hilo, não para o espaço pleural.", "d": "Incorreta. Existe uma pequena quantidade de proteínas (cerca de 1-1,5 g/dL) no líquido normal.", "e": "Incorreta. O sistema linfático é o principal regulador do equilíbrio entre entrada e saída de líquido."}, "difficulty": "dificil", "tags": ["Pneumologia", "Fisiologia", "Starling", "Linfáticos"]}'::jsonb, 121, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico de amiloidose sistêmica com acometimento pleural, qual o achado padrão-ouro na biópsia pleural?", "options": {"a": "Granulomas não caseificantes.", "b": "Deposição de material amorfo eosinofílico com birrefringência verde-maçã sob luz polarizada após coloração de Vermelho Congo.", "c": "Invasão de células musculares lisas atípicas.", "d": "Presença de corpúsculos de ferrugem (Asbestos bodies).", "e": "Fibrina densa com neutrófilos."}, "answer": "b", "rationale": "A amiloidose pleural é uma causa rara de exsudato linfocítico crônico. O diagnóstico exige a biópsia (parietal ou pulmonar) com a coloração de Vermelho Congo, demonstrando a birrefringência clássica do material amiloide.", "option_rationales": {"a": "Incorreta. Característico da sarcoidose.", "b": "Correta. Padrão-ouro histopatológico para amiloidose.", "c": "Incorreta. Característico da Linfangioleiomiomatose (LAM).", "d": "Incorreta. Indica exposição ao asbesto.", "e": "Incorreta. Indica empiema organizado."}, "difficulty": "media", "tags": ["Pneumologia", "Patologia", "Amiloidose", "Biópsia Pleural"]}'::jsonb, 122, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista crônico apresenta derrame pleural à direita. A análise mostra: pH 7,38, Glicose 105, Proteína 3,6 (Sérica 6,2), LDH 400 (Sérico 350). Citologia oncótica: células malignas compatíveis com adenocarcinoma de pulmão. É solicitada a pesquisa de mutações driver no líquido. Qual é a vantagem de se utilizar o ''bloco de células'' (cell block) em vez da citometria de fluxo ou esfregaço isolado?", "options": {"a": "O cell block permite a análise da arquitetura tecidual e a realização de múltiplas colorações imuno-histoquímicas em cortes seriados.", "b": "O cell block é mais rápido, ficando pronto em 15 minutos.", "c": "Não há vantagem, sendo o esfregaço superior em todos os casos.", "d": "O cell block evita a necessidade de centrífuga.", "e": "Apenas o cell block consegue detectar bactérias."}, "answer": "a", "rationale": "O ''Cell Block'' processa as células do líquido pleural como se fossem um fragmento de tecido de biópsia. Isso permite ao patologista realizar cortes seriados no bloco de parafina e aplicar um painel extenso de imuno-histoquímica (necessário para diferenciar mesotelioma de adenocarcinoma e identificar o sítio primário), além de disponibilizar material para testes moleculares (EGFR, ALK, PD-L1).", "option_rationales": {"a": "Correta. Razão principal para o processamento de cell block em oncologia pleural.", "b": "Incorreta. O processamento em parafina leva horas a dias.", "c": "Incorreta. O esfregaço é bom para morfologia individual, mas limitado para painéis imuno-histoquímicos complexos.", "d": "Incorreta. A centrífuga é necessária para concentrar as células para o bloco.", "e": "Incorreta. Bactérias podem ser vistas em qualquer método citológico se a carga for alta, embora o Gram/Cultura sejam os métodos de escolha."}, "difficulty": "media", "tags": ["Pneumologia", "Patologia", "Oncologia", "Cell Block"]}'::jsonb, 123, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 55 anos apresenta derrame pleural volumoso recorrente. Estuda-se a realização de pleurodese química. Qual a importância de se medir o pH pleural e o grau de reexpansão pulmonar ANTES de realizar o procedimento?", "options": {"a": "Não têm importância, a pleurodese deve ser feita em todos.", "b": "pH < 7,10 e falha na reexpansão (pulmão encarcerado) predizem alto risco de falha da pleurodese.", "c": "Apenas a idade do paciente importa.", "d": "Se o pH for normal, a pleurodese é contraindicada.", "e": "Pulmão encarcerado é a indicação absoluta de talco insuflado (poudrage)."}, "answer": "b", "rationale": "A pleurodese exige o contato entre as duas pleuras após a drenagem para que o processo inflamatório leve à sínfise. Se o pulmão estiver encarcerado (não expande), as pleuras não se tocam e o procedimento falha. Além disso, derrames com pH muito baixo em oncologia costumam refletir grande carga tumoral e pleura espessada, o que também diminui a chance de sucesso da pleurodese química.", "option_rationales": {"a": "Incorreta. Taxa de falha pode ser alta em casos mal selecionados.", "b": "Correta. São os dois principais preditores de sucesso/falha do procedimento.", "c": "Incorreta. Status funcional e expansibilidade são os critérios chave.", "d": "Incorreta. pH normal é favorável à pleurodese.", "e": "Incorreta. Poudrage também exige contato pleural para funcionar."}, "difficulty": "media", "tags": ["Pneumologia", "Terapêutica", "Pleurodese", "Pulmão Encarcerado"]}'::jsonb, 124, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual dos seguintes parâmetros no líquido pleural ajuda a distinguir com segurança o Quilotórax (linfa) do Pseudoquilotórax (coleção crônica de colesterol)?", "options": {"a": "O aspecto macroscópico, pois apenas o quilotórax é leitoso.", "b": "A dosagem de triglicerídeos > 110 mg/dL e a presença de quilomícrons favorecem Quilotórax.", "c": "O pH, que é alcalino apenas no pseudoquilotórax.", "d": "A presença de cristais rômbicos favorece quilotórax agudo.", "e": "O ADA elevado é típico de quilotórax."}, "answer": "b", "rationale": "O diagnóstico diferencial clínico/químico baseia-se nos lipídios: Quilotórax tem TG alto (> 110) e Quilomícrons. Pseudoquilotórax tem TG baixo, mas colesterol muito alto (> 200 mg/dL) e presença de cristais de colesterol (rômbicos).", "option_rationales": {"a": "Incorreta. Ambos podem ter aspecto leitoso ou ''opalescente''.", "b": "Correta. Parâmetro bioquímico confirmatório para quilo verdadeiro.", "c": "Incorreta. Não é um critério de diferenciação.", "d": "Incorreta. Cristais de colesterol são do pseudoquilotórax crônico.", "e": "Incorreta. ADA alto é de TB ou AR."}, "difficulty": "media", "tags": ["Pneumologia", "Bioquímica", "Quilotórax", "Lipídios"]}'::jsonb, 125, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Na abordagem do derrame parapneumônico loculado, o uso de fibrinolíticos intrapleurais (ex: tPA associado à DNase) demonstrou quais benefícios de acordo com o estudo MIST-2?", "options": {"a": "Redução da mortalidade em 50%.", "b": "Melhora da drenagem radiológica e redução da necessidade de cirurgia invasiva, mas sem impacto provado na mortalidade.", "c": "Aumento do risco de sangramento sem qualquer benefício terapêutico.", "d": "Substituição completa do uso de antibióticos venosos.", "e": "Cura de derrames por Tuberculose de forma acelerada."}, "answer": "b", "rationale": "O ensaio MIST-2 mostrou que a combinação de tPA (para quebrar a fibrina) e DNase (para reduzir a viscosidade do pus por lise de DNA de neutrófilos) melhora significativamente a drenagem e reduz a indicação de cirurgia (VATS/Decorticação) em pacientes com derrames parapneumônicos multiloculados.", "option_rationales": {"a": "Incorreta. Nenhum estudo provou redução de mortalidade absoluta direta apenas pelo fibrinolítico isolado.", "b": "Correta. Melhora do desfecho secundário de evitar cirurgia agressiva.", "c": "Incorreta. Há risco de sangramento, mas o benefício em casos selecionados supera o risco.", "d": "Incorreta. Antibióticos são obrigatórios.", "e": "Incorreta. Fibrinolíticos não têm papel na TB pleural isolada."}, "difficulty": "dificil", "tags": ["Pneumologia", "Evidência", "Empiema", "Fibrinolíticos"]}'::jsonb, 126, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente em uso crônico de Amiodarona para tratamento de arritmia desenvolve derrame pleural bilateral e infiltrado pulmonar reticular fino. A biópsia pulmonar e pleural revela a presença de macrófagos com citoplasma ''espumoso'' (foam cells). Este achado é:", "options": {"a": "Sinal patognomônico de toxicidade pulmonar pela Amiodarona.", "b": "Sinal de exposição à droga, mas não necessariamente de toxicidade estabelecida (pode ocorrer em pacientes assintomáticos que usam a medicação).", "c": "Indicação imediata de quimioterapia para linfoma.", "d": "Sinal de infecção por Pneumocystis jirovecii.", "e": "Característico de edema agudo de pulmão por falha do ventrículo esquerdo."}, "answer": "b", "rationale": "A presença de ''foam cells'' (macrófagos com lamelas fosfolipídicas por inibição da fosfolipase pela droga) indica que o paciente está impregnado pela Amiodarona, mas não confirma que a inflamação e o derrame sejam causados exclusivamente pela toxicidade. O diagnóstico de toxicidade pulmonar é de exclusão, baseando-se no quadro clínico, radiológico e resposta à suspensão da droga.", "option_rationales": {"a": "Incorreta. Muitos usuários da droga têm essas células sem ter doença pulmonar ativa.", "b": "Correta. Distinção importante de patologia: exposição vs doença.", "c": "Incorreta. Não indica malignidade.", "d": "Incorreta. Pneumocystis apresenta exsudato espumoso ''intra-alveolar'' característico, mas as ''foam cells'' de macrófagos são clássicas da Amiodarona.", "e": "Incorreta. Congestão causa macrófagos com hemossiderina (Heart failure cells)."}, "difficulty": "dificil", "tags": ["Pneumologia", "Farmacodinâmica", "Amiodarona", "Efeitos Colaterais"]}'::jsonb, 127, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A fístula Colecistopleural é uma causa extremamente rara de derrame pleural. Qual a coloração característica do líquido pleural neste cenário clínico?", "options": {"a": "Hemorrágica.", "b": "Leitosa.", "c": "Esverdeada ou amarelada (bile), com dosagem de Bilirrubina Pleural / Bilirrubina Sérica > 1,0.", "d": "Preta ou marrom escuro.", "e": "Líquido viscoso transparente."}, "answer": "c", "rationale": "Também chamado de ''Biliotórax'', ocorre pela fístula entre o sistema biliar e o espaço pleural (frequentemente após trauma ou procedimentos hepáticos). A confirmação diagnóstica é a relação de bilirrubina pleural/sérica maior que 1, além do aspecto biliar do líquido.", "option_rationales": {"a": "Incorreta. Sangue na pleura.", "b": "Incorreta. Linfa ou colesterol.", "c": "Correta. Biliotórax diagnóstica bioquímica.", "d": "Incorreta. Infecção por Aspergillus niger ou ruptura de cisto melânico.", "e": "Incorreta. Mesotelioma (ácido hialurônico)."}, "difficulty": "media", "tags": ["Pneumologia", "Gastroenterologia", "Bioquímica", "Biliotórax"]}'::jsonb, 128, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal causa de morte imediata por acidente punção durante uma toracocentese diagnóstica realizada por via posterior?", "options": {"a": "Choque vagal.", "b": "Lesão do fígado ou baço (hemoperitônio maciço por punção transdiafragmática).", "c": "Pneumotórax bilateral.", "d": "Laceração da aorta descendente.", "e": "Edema agudo de pulmão."}, "answer": "b", "rationale": "Punções muito baixas (abaixo do 9º espaço intercostal) ou sem guia de ultrassom podem levar à passagem da agulha pelo diafragma e lesão de órgãos sólidos abdominais (baço à esquerda, fígado à direita). O hemoperitônio resultante pode ser volumoso e levar ao choque antes mesmo que o médico perceba o erro intra-abdominal no procedimento torácico.", "option_rationales": {"a": "Incorreta. Grave, mas raramente letal com manobras simples.", "b": "Correta. Acidente anatômico grave potencial.", "c": "Incorreta. Raro agulha puncionar os dois lados simultaneamente.", "d": "Incorreta. A aorta é medial e o trajeto da punção costuma ser lateral/linha axilar.", "e": "Incorreta. Complicação tardia de drenagem volumosa, não do acidente de punção imediato."}, "difficulty": "media", "tags": ["Pneumologia", "Procedimentos", "Anatomia", "Complicações"]}'::jsonb, 129, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No hemotórax traumático, o sangue no espaço pleural tende a se coagular rapidamente, o que dificulta a drenagem por cateteres finos. No entanto, por que o sangue costuma ser aspirado em estado líquido nas primeiras horas após o trauma?", "options": {"a": "O pulmão produz heparina natural em doses cavalares.", "b": "A desfibrinação do sangue ocorre pelos movimentos respiratórios e cardíacos, transformando o fibrinogênio em fibrina que se deposita nas superfícies pleurais.", "c": "O sangue pleural nunca coagula.", "d": "O líquido pleural transuda água para o sangue, diluindo os fatores de coagulação.", "e": "As bactérias pleurais consomem as plaquetas."}, "answer": "b", "rationale": "O sangue no espaço pleural sofre um processo de desfibrinação mecânica por agitação física do coração e pulmões. A fibrina precipita-se sobre a pleura e o líquido remanescente (soro sanguineo) permanece incoagulável in vitro. Se o sangramento for maciço e rápido, o sistema de desfibrinação falha, formando coágulos sólidos que bloqueiam drenos.", "option_rationales": {"a": "Incorreta. Explicação fictícia.", "b": "Correta. Fenômeno fisiopatológico do hemotórax.", "c": "Incorreta. Coagula sim, e pode gerar empiema coagulado/pseudotumor hemático.", "d": "Incorreta. Pelo contrário, o sangue irrita a pleura e gera exsudato adicionando proteína.", "e": "Incorreta. Não ocorre em condições traumáticas imediatas."}, "difficulty": "dificil", "tags": ["Pneumologia", "Fisiopatologia", "Hemotórax", "Coagulação"]}'::jsonb, 130, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A presença de ''linfangite carcinomatosa'' na radiografia e TC de tórax (espessamento nodular de septos interlobulares) em um paciente com derrame pleural maligno unilateral, aponta para qual mecanismo adicional de formação do líquido?", "options": {"a": "Aumento da pressão hidrostática arterial.", "b": "Bloqueio da drenagem linfática pleural e pulmonar retrógrada.", "c": "Redução acentuada da permeabilidade capilar.", "d": "Invasão direta do esôfago pelo tumor.", "e": "Hipotireoidismo paraneoplásico."}, "answer": "b", "rationale": "A linfangite carcinomatosa reflete a invasão dos vasos linfáticos pulmonares por células neoplásicas. Isso causa um bloqueio mecânico severo à drenagem linfática pleural, que é a principal via de saída de líquido e proteínas. O resultado é um derrame volumoso, recidivante e de difícil controle clínico.", "option_rationales": {"a": "Incorreta. Mecanismo de transudato cardíaco.", "b": "Correta. Mecanismo principal de derrames neoplásicos de grandes volumes.", "c": "Incorreta. O câncer aumenta a permeabilidade.", "d": "Incorreta. Daria derrame purulento/alimentar.", "e": "Incorreta. Hipotireoidismo não causa linfangite radiológica."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Linfangite Carcinomatosa", "Fisiopatologia"]}'::jsonb, 131, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 40 anos apresenta derrame pleural bilateral assintomático, ascite e edema de membros inferiores. A análise do líquido pleural é um transudato. A dosagem de albumina sérica é de 1,6 g/dL e a proteinúria de 24 horas é de 12 gramas. Qual a causa do derrame pleural?", "options": {"a": "Cirrose Hepática.", "b": "Insuficiência Cardíaca Congestiva.", "c": "Síndrome Nefrótica.", "d": "Tuberculose Peritoneal.", "e": "Sarcoidose Sistêmica."}, "answer": "c", "rationale": "A proteinúria maciça (> 3,5g/dia) e a hipoalbuminemia grave definem a síndrome nefrótica. O derrame pleural ocorre pela queda drástica da pressão oncótica plasmática, permitindo a transudação de líquido para o espaço pleural (frequentemente bilateral e associado a anasarca).", "option_rationales": {"a": "Incorreta. Cirrose daria ascite desproporcional e albumina baixa, mas não proteinúria de 12g.", "b": "Incorreta. ICC causa derrame, mas não explica a perda urinária de proteína.", "c": "Correta. Quadro laboratorial clássico de necrose glomerular/síndrome nefrótica.", "d": "Incorreta. TB seria exsudato.", "e": "Incorreta. Sarcoidose pode dar nefrite, mas o quadro nefrótico franco com transudato pleural não é sua manifestação principal."}, "difficulty": "facil", "tags": ["Pneumologia", "Nefrologia", "Transudato", "Síndrome Nefrótica"]}'::jsonb, 132, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A presença de ''corpos psamomatosos'' (psammoma bodies) no estudo citológico do líquido pleural é um achado sugestivo de quais tipos de câncer primário?", "options": {"a": "Carcinoma de pulmão de grandes células.", "b": "Adenocarcinoma de ovário, de tireoide ou mesotelioma.", "c": "Leucemia mieloide.", "d": "Câncer de próstata.", "e": "Linfoma de Burkitt."}, "answer": "b", "rationale": "Os corpos psamomatosos são calcificações concêntricas microscópicas. Embora clássicos no carcinoma papilífero da tireoide e no seroso de ovário, também podem ser encontrados em mesoteliomas pleurais e adenocarcinomas de pulmão, sendo um forte indício de neoplasia epitelial papilar.", "option_rationales": {"a": "Incorreta. Menos comum.", "b": "Correta. Achado citopatológico de valor diagnóstico.", "c": "Incorreta. Neoplasias hematológicas não formam calcificações psamomatosas.", "d": "Incorreta. Não é o padrão.", "e": "Incorreta. Linfomas não apresentam esses corpúsculos."}, "difficulty": "dificil", "tags": ["Pneumologia", "Oncologia", "Citopatologia", "Corpos Psamomatosos"]}'::jsonb, 133, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 30 anos apresenta quadro de dor abdominal, náuseas e vômitos, seguido de dispneia e derrame pleural à esquerda 24h após o quadro inicial. A dosagem de amilase pleural é de 1.100 U/L (Sérica 950 U/L). RX de abdome sem pneumoperitônio. Qual a interpretação mais provável?", "options": {"a": "Ruptura esofágica aguda.", "b": "Derrame pleural simpático secundário a Pancreatite Aguda.", "c": "Adenocarcinoma gástrico metastático.", "d": "Tuberculose Pleural.", "e": "Derrame por trauma de baço."}, "answer": "b", "rationale": "A elefvação da amilase pleural ocorre em cerca de 10% das pancreatites agudas. O derrame costuma ser à esquerda pelo contato do pâncreas com o diafragma esquerdo. Diferente da fístula pancreática crônica, a amilase aqui costuma subir em paralelo à sérica ou levemente acima dela.", "option_rationales": {"a": "Incorreta. Daria amilase salivar (isoforma salivar) muito mais alta e quadro clínico de mediastinite grave.", "b": "Correta. Associação clássica aguda.", "c": "Incorreta. Câncer gástrico eleva amilase raramente e não de forma tão aguda.", "d": "Incorreta. TB não cursa com amilase alta.", "e": "Incorreta. Trauma de baço dá hemotórax, não elevação de amilase."}, "difficulty": "media", "tags": ["Pneumologia", "Gastroenterologia", "Pancreatite Aguda", "Amilase"]}'::jsonb, 134, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal limitação da biópsia pleural por agulha ''cega'' (e.g., Abrams) no diagnóstico do Mesotelioma Maligno?", "options": {"a": "A agulha é grossa demais e causa pneumotórax sempre.", "b": "O mesotelioma acomete a pleura de forma focal/nodular no início, e a biópsia cega pode captar apenas áreas de pleurite inflamatória reativa entre os nódulos tumorais.", "c": "O talco nas luvas do patologista impede o diagnóstico.", "d": "A agulha de Abrams só pode ser usada na pleura visceral.", "e": "O mesotelioma não é visível no microscópio comum."}, "answer": "b", "rationale": "Assim como o adenocarcinoma pleural, o mesotelioma pode crescer em placas ou nódulos. A biópsia cega tem um ''erro de amostragem'' inerente. Um resultado negativo em biópsia cega não exclui o diagnóstico, exigindo biópsia dirigida por imagem ou por VATS se a suspeita persistir.", "option_rationales": {"a": "Incorreta. Risco de pneumotórax existe, mas não é a limitação diagnóstica principal (biológica).", "b": "Correta. Limitação fundamental da técnica cega em patologias nodulares.", "c": "Incorreta. Não interfere.", "d": "Incorreta. Abrams biópsia exclusivamente pleura parietal.", "e": "Incorreta. É visível sim."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Mesotelioma", "Biópsia Cega"]}'::jsonb, 135, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A dosagem de ácido hialurônico (hialuronato) no líquido pleural foi historicamente proposta como um marcador para qual neoplasia específica da pleura?", "options": {"a": "Linfoma de Burkitt.", "b": "Adenocarcinoma de pulmão.", "c": "Mesotelioma Maligno.", "d": "Tumor Fibroso Solitário.", "e": "Angiossarcoma."}, "answer": "c", "rationale": "Células mesoteliais malignas produzem grandes quantidades de ácido hialurônico. Valores > 100 mg/L no líquido pleural são muito sugestivos de mesotelioma, embora a técnica de dosagem não seja rotineiramente disponível em todos os laboratórios.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Marcador bioquímico clássico da biologia mesotelial.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Pneumologia", "Bioquímica", "Mesotelioma", "Marcadores"]}'::jsonb, 136, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em pacientes submetidos à diálise peritoneal, a ocorrência de derrame pleural volumoso à direita (''Hidrotórax doce'') é causada pela fístula pleuro-peritoneal. Por qual motivo a coloração de Gram e a cultura do líquido pleural devem ser realizadas nestes pacientes, mesmo com suspeita de transudato?", "options": {"a": "Para confirmar o ''gosto'' doce do líquido.", "b": "Porque pacientes em diálise têm alta taxa de colonização pleural por fungos.", "c": "Para rastrear peritonite bacteriana que pode ter translocado junto com o dialisado através da fístula diafragmática.", "d": "É uma rotina administrativa desnecessária clínica.", "e": "A glicose alta atrai bactérias da pele durante a toracentese."}, "answer": "c", "rationale": "A fístula diafragmática permite que não apenas o líquido de diálise, mas também qualquer processo infeccioso peritoneal (peritonite por contaminação do cateter de diálise) se espalhe para a pleura, transformando um hidrotórax mecânico em um empiema/pleurite bacteriana.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta. Menos comum que a bacteriana.", "c": "Correta. Raciocínio clínico sobre fístulas serosas.", "d": "Incorreta. Tem valor diagnóstico e terapêutico.", "e": "Incorreta. Explicação fictícia."}, "difficulty": "media", "tags": ["Pneumologia", "Nefrologia", "Diálise", "Peritonite"]}'::jsonb, 137, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Biópsia Pleural por Agulha'' é contraindicada ou apresenta risco inaceitável em qual das seguintes situações?", "options": {"a": "Presença de loculações pleurais.", "b": "Derrame pleural muito pequeno (lâmina de líquido < 1 cm na radiografia de Laurell) sem guia de imagem.", "c": "Paciente com febre acima de 39°C.", "d": "Uso de oxigênio por cateter nasal.", "e": "Idade inferior a 18 anos."}, "answer": "b", "rationale": "Puncionar a pleura com agulha de biópsia (que tem uma abertura cortante lateral) quando há pouco líquido coloca o pulmão e o diafragma em risco imediato de laceração. Exige técnica guiada por imagem (US ou TC) ou drenagem prévia/preenchimento com ar em técnicas antigas hoje obsoletas.", "option_rationales": {"a": "Incorreta. Pode ser feita guiada por imagem justamente na loculação.", "b": "Correta. Regra de segurança em procedimentos invasivos cegos.", "c": "Incorreta. Febre não contraindica a biópsia diagnóstica.", "d": "Incorreta. Paciente hipoxêmico pode e deve ser diagnosticado.", "e": "Incorreta. Crianças podem ser biopsiadas."}, "difficulty": "media", "tags": ["Pneumologia", "Procedimentos", "Segurança", "Contraindicações"]}'::jsonb, 138, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal função fisiológica da pleura visceral?", "options": {"a": "Produzir 90% do líquido pleural diário.", "b": "Absorver proteínas do espaço pleural.", "c": "Facilitar o deslizamento pulmonar durante a respiração e manter a anatomia lobar através das cisuras.", "d": "Proteger o coração contra infecções bacterianas.", "e": "Filtrar o ar inspirado."}, "answer": "c", "rationale": "A pleura visceral reveste o pulmão e permite o deslizamento suave contra a pleura parietal graças à fina camada de líquido pleural (lubrificante). Suas invaginações (cisuras) dividem os pulmões em lobos, garantindo a expansibilidade e limitando a propagação de patologias em alguns cenários.", "option_rationales": {"a": "Incorreta. Produção é majoritariamente parietal.", "b": "Incorreta. Absorção é quase exclusiva da parietal via estomas linfáticos.", "c": "Correta. Função mecânica e anatômica fundamental.", "d": "Incorreta. Função do pericárdio.", "e": "Incorreta. Função do epitélio respiratório e cílios."}, "difficulty": "facil", "tags": ["Pneumologia", "Anatomia", "Fisiologia"]}'::jsonb, 139, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 38 anos apresenta febre alta diária em picos, odinofagia, artralgias e rash cutâneo fugaz (cor salmão) no tronco durante os episódios febris. Ao exame físico, observa-se esplenomegalia. Laboratório mostra leucocitose importante (neutrofilia) e ferritina sérica de 8.000 ng/mL. A radiografia de tórax revela pequeno derrame pleural bilateral (exsudato neutrofílico). Qual o diagnóstico mais provável?", "options": {"a": "Linfoma de Hodgkin.", "b": "Lúpus Eritematoso Sistêmico.", "c": "Doença de Still do Adulto.", "d": "Tuberculose Miliar.", "e": "Febre Reumática."}, "answer": "c", "rationale": "A Doença de Still do Adulto é uma síndrome autoinflamatória caracterizada pela tríade: febre alta, artrite/artralgia e rash salmão evanescente. A ferritina muito elevada e a leucocitose neutrofílica são marcos laboratoriais. O envolvimento de serosites (pleurite e pericardite) ocorre em cerca de 30-40% dos casos.", "option_rationales": {"a": "Incorreta. O rash e a ferritina astronômica favorecem Still.", "b": "Incorreta. Lúpus costuma ter leucopenia e outros anticorpos positivos; o rash é malar e fixo.", "c": "Correta. Descrição clássica da doença e seus achados pleurais.", "d": "Incorreta. Embora cause febre e serosite, não explica o rash fugaz e a ferritina tão alta.", "e": "Incorreta. Quadro clínico e perfil laboratorial distintos."}, "difficulty": "dificil", "tags": ["Pneumologia", "Reumatologia", "Doença de Still", "Ferritina"]}'::jsonb, 140, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico diferencial de nódulos pleurais, a Tomografia por Emissão de Pósitrons (PET-CT) com FDG-18 pode apresentar resultados FALSO-POSITIVOS (captação aumentada sem câncer) em qual das seguintes situações prévias?", "options": {"a": "Toracocentese diagnóstica realizada há 1 ano.", "b": "Histórico de pleurodese com talco (Talc Poudrage ou Slurry) realizada anteriormente.", "c": "Derrame pleural transudativo por ICC.", "d": "Uso de corticoides inalatórios.", "e": "Vacinação contra influenza."}, "answer": "b", "rationale": "O talco induz uma reação inflamatória granulomatosa crônica na pleura que é metabolicamente ativa e pode captar FDG intensamente no PET-CT por muitos anos. Isso dificulta a detecção de recidivas tumorais ou novos nódulos malignos na pleura ''talcada''.", "option_rationales": {"a": "Incorreta. Cicatriz mínima sem atividade metabólica persistente.", "b": "Correta. Causa clássica de falso-positivo em PET torácico.", "c": "Incorreta. Transudatos não captam FDG.", "d": "Incorreta. Corticoides podem até reduzir a captação inflamatória.", "e": "Incorreta. Sem relação com a pleura."}, "difficulty": "media", "tags": ["Pneumologia", "Medicina Nuclear", "PET-CT", "Pleurodese"]}'::jsonb, 141, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista pesado apresenta derrame pleural volumoso recorrente. A citologia oncótica é positiva para carcinoma, mas o tipo celular é ''indiferenciado''. O painel de imuno-histoquímica no cell block mostra: CK7 (+), CK20 (-), TTF-1 (+), Napsina A (+). Qual o sítio primário mais provável?", "options": {"a": "Cólon.", "b": "Mama.", "c": "Pulmão (Adenocarcinoma).", "d": "Estômago.", "e": "Rim (Carcinoma de células claras)."}, "answer": "c", "rationale": "O perfil CK7+ / CK20- associado à positividade de TTF-1 (Thyroid Transcription Factor-1) e Napsina A é altamente específico para o adenocarcinoma primário do pulmão. O TTF-1 positivo também pode ocorrer em tumores de tireoide, mas a Napsina A e o quadro clínico confirmam a origem pulmonar.", "option_rationales": {"a": "Incorreta. Cólon costuma ser CK20+ / CK7- / CDX2+.", "b": "Incorreta. Mama costuma ser GATA3+ / Mamaglobina+.", "c": "Correta. Algoritmo diagnóstico clássico da patologia pulmonar.", "d": "Incorreta. Estômago costuma ser CK7/CK20 variável.", "e": "Incorreta. Rim costuma ser PAX-8+ / RCC+."}, "difficulty": "media", "tags": ["Pneumologia", "Patologia", "Imuno-histoquímica", "Adenocarcinoma"]}'::jsonb, 142, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Após uma cirurgia de Pneumonectomia Direta (retirada total do pulmão), o espaço vazio no hemitórax é preenchido gradualmente por líquido e ocorre o desvio do mediastino. Qual fenômeno é esperado no ''espaço pós-pneumonectomia'' em um paciente com evolução normal no primeiro mês?", "options": {"a": "O espaço deve ser preenchido por ar e permanecer vazio para sempre.", "b": "Ocorre preenchimento por líquido (derramesinoso) e desvio do mediastino para o lado da cirurgia (ipsilateral).", "c": "O mediastino deve ser empurrado para o lado oposto (contralateral) pelo líquido.", "d": "Indica-se a colocação de um dreno de tórax em selo d''água permanente.", "e": "O pulmão contralateral deve herniar para o lado operado imediatamente."}, "answer": "b", "rationale": "No pós-operatório estável de pneumonectomia, o hemitórax operado é preenchido por fluido sero-hemorrágico (derramamento pós-pneumonectomia) e o mediastino desvia-se para o lado operado (ipsilateral) à medida que o líquido é organizado e ocorre a redução volumétrica da cavidade. Se o mediastino desviar para o lado oposto, deve-se suspeitar de empiema ou hemorragia maciça.", "option_rationales": {"a": "Incorreta. O ar seria sinal de fístula ou erro de técnica.", "b": "Correta. Evolução radiológica e fisiológica esperada.", "c": "Incorreta. Indica tensão no espaço pleural (complicação).", "d": "Incorreta. A drenagem na pneumonectomia é feita com cautela ou nem é feita para evitar desvios súbitos do mediastino.", "e": "Incorreta. A hérnia pulmonar contralateral leva tempo para ocorrer (meses/anos)."}, "difficulty": "dificil", "tags": ["Pneumologia", "Cirurgia Torácica", "Pneumonectomia", "Fisiologia"]}'::jsonb, 143, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurite Reumatoide'' é uma causa de exsudato crônico. Qual parâmetro laboratorial no líquido pleural da artrite reumatoide costuma apresentar valores extremamente ELEVADOS, muitas vezes superando os níveis séricos?", "options": {"a": "Glicose.", "b": "Ph (alcalino).", "c": "Fator Reumatoide (FR).", "d": "Células mesoteliais (> 20%).", "e": "Triglicerídeos."}, "answer": "c", "rationale": "No derrame pleural da artrite reumatoide, os títulos de Fator Reumatoide no líquido são tipicamente maiores ou iguais aos títulos séricos (geralmente > 1:320). Além disso, a glicose é muito baixa e o LDH muito alto.", "option_rationales": {"a": "Incorreta. Glicose é mínima por bloqueio de transporte.", "b": "Incorreta. Ph é ácido devido à intensa inflamação e glicólise.", "c": "Correta. Característica imunológica do derrame reumatoide.", "d": "Incorreta. As mesoteliais costumam ser raras por espessamento pleural.", "e": "Incorreta. Sem relação direta, a menos que haja pseudoquilotórax associado."}, "difficulty": "media", "tags": ["Pneumologia", "Reumatologia", "Artrite Reumatoide", "FR"]}'::jsonb, 144, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico do Mieloma Múltiplo com acometimento pleural (Derrame Pleural por Mieloma), qual é a característica definitiva do líquido pleural?", "options": {"a": "Presença de granulomas caseosos.", "b": "Citologia oncótica demonstrando plasmócitos neoplásicos (> 50% das células nucleadas) e presença de componente monoclonal (pico gama) na eletroforese de proteínas do líquido.", "c": "Transudato rico em albumina.", "d": "Amilase pleural elevada.", "e": "Odor fétido e pH alto."}, "answer": "b", "rationale": "O envolvimento pleural direto pelo mieloma é raro (< 1% dos casos). O diagnóstico é feito pela visualização de plasmócitos atípicos no líquido e pela demonstração da proteína monoclonal (paraproteína) no próprio derrame, confirmando a infiltração plasmocitária maligna da pleura.", "option_rationales": {"a": "Incorreta. Indica TB.", "b": "Correta. Critérios diagnósticos hematológicos aplicados à pleura.", "c": "Incorreta. Mieloma infiltrativo causa exsudato.", "d": "Incorreta. Não associada.", "e": "Incorreta. Indica empiema por anaeróbios."}, "difficulty": "dificil", "tags": ["Pneumologia", "Hematologia", "Mieloma Múltiplo", "Plasmócitos"]}'::jsonb, 145, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente idoso, hígido até o momento, apresenta quadro de dor torácica súbita e derrame pleural hemorrágico à direita. A tomografia revela ruptura de um pequeno ramo de artéria intercostal sem história de trauma evidente. Este fenômeno é conhecido como:", "options": {"a": "Hemotórax espontâneo por esforço (咳嗽).", "b": "Hemotórax Idiopático.", "c": "Hemotórax por Fragilidade Capilar Senil.", "d": "Aneurisma de artéria intercostal roto espontaneamente.", "e": "Dissecção aórtica tipo B."}, "answer": "d", "rationale": "Aneurismas verdadeiros ou pseudoaneurismas das artérias intercostais podem romper espontaneamente (ou após tosse vigorosa), causando hemotórax maciço sem trauma. O diagnóstico é angiográfico e o tratamento pode ser por embolização transcateter ou cirurgia.", "option_rationales": {"a": "Incorreta. Termo não padronizado para esta etiologia específica.", "b": "Incorreta. Sempre deve-se buscar a causa vascular oculta.", "c": "Incorreta. Termo técnico inexistente nesta patologia.", "d": "Correta. Causa importante de hemotórax não traumático em idosos.", "e": "Incorreta. Dissecção de aorta causa outros achados na TC, embora também possa dar hemotórax (geralmente à esquerda)."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Vascular", "Hemotórax Espontâneo"]}'::jsonb, 146, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A medição do pH do líquido pleural em pacientes com Derrame Pleural Maligno apresenta qual valor prognóstico?", "options": {"a": "Nenhum valor.", "b": "pH < 7,30 está associado a uma menor sobrevida e menor chance de sucesso na pleurodese química.", "c": "pH alcalino (> 7,6) indica cura iminente.", "d": "pH baixo indica que o paciente deve receber antibióticos.", "e": "Indica o tipo histológico do câncer (ex: epidermoide vs adenocarcinoma)."}, "answer": "b", "rationale": "No derrame maligno, o pH ácido reflete uma alta carga metabólica tumoral, pleura mais infiltrada e espessada. Isso correlaciona-se com menor tempo de sobrevida global desses pacientes e com taxas de falha de pleurodese de até 50-70%.", "option_rationales": {"a": "Incorreta. Tem alto valor prognóstico validado.", "b": "Correta. pH baixo = Doença mais agressiva/avançada na pleura.", "c": "Incorreta. pH alcalino é raro e sem este significado.", "d": "Incorreta. Ph baixo no câncer não indica infecção, mas sim atividade tumoral/inflamatória.", "e": "Incorreta. Ph baixo ocorre em qualquer subtipo histológico avançado."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Prognóstico", "pH Pleural"]}'::jsonb, 147, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente submetido à colocação de cateter venoso central na veia subclávia esquerda desenvolve derrame pleural esquerdo volumoso logo após o início da infusão de dieta parenteral (NPT). O líquido pleural coletado tem aspecto leitoso e os valores de glicose e lipídios são idênticos à solução de NPT infundida. Qual a complicação?", "options": {"a": "Quilotórax por lesão do ducto torácico.", "b": "Infusão intrapleural inadvertida devido à migração ou mau posicionamento do cateter venoso central (Quilotórax iatrogênico fictício).", "c": "Empiema por contaminação da dieta.", "d": "Pseudoquilotórax agudo.", "e": "Derrame de colesterol iatrogênico."}, "answer": "b", "rationale": "Este é um quadro clássico de complicação de acesso venoso central. O cateter perfura a veia e a pleura, e a infusão de lípidos (contidos na NPT) simula macroscopicamente um quilotórax. A análise química igual à do frasco de infusão confirma o acidente de punção/posicionamento.", "option_rationales": {"a": "Incorreta. O ducto torácico desemboca na junção subclávia/jugular esquerda; sua lesão daria quilo real, mas o quadro imediato pós-infusão com química idêntica aponta para o cateter no espaço pleural.", "b": "Correta. Acidente evitável com RX de controle pós-punção.", "c": "Incorreta. Quadro súbito logo após o início da infusão não é tempo para empiema.", "d": "Incorreta. Pseudoquilotórax leva meses para se formar.", "e": "Incorreta. Termo não aplicável."}, "difficulty": "facil", "tags": ["Pneumologia", "Terapia Intensiva", "Iatrogenia", "NPT"]}'::jsonb, 148, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em relação à ventilação mecânica com pressão positiva (PEEP), qual o efeito esperado na detecção do líquido pleural por radiografia de tórax?", "options": {"a": "Aumenta a facilidade de ver pequenas quantidades de líquido.", "b": "O PEEP alto pode ''esconder'' o derrame pleural mascarando a opacidade pelo aumento da aeração do parênquima ou por redistribuição compressiva do líquido.", "c": "Dificulta a realização de ultrassom.", "d": "Causa desaparecimento total do líquido por evaporação interna.", "e": "Sempre causa pneumotórax hipertensivo em derrames pequenos."}, "answer": "b", "rationale": "A pressão positiva reexpande áreas de atelectasia e empurra o líquido pleural para posições mais inferiores ou laterais, o que pode reduzir o ''velamento'' clássico na radiografia e fazer com que o volume do derrame pareça menor do que realmente é.", "option_rationales": {"a": "Incorreta. Pelo contrário, tende a mascarar.", "b": "Correta. Desafio radiológico no paciente crítico em UTI.", "c": "Incorreta. O ultrassom continua sendo muito sensível independentemente do PEEP.", "d": "Incorreta. Explicação absurda.", "e": "Incorreta. Risco de barotrauma existe, mas não é regra absoluta."}, "difficulty": "media", "tags": ["Pneumologia", "Terapia Intensiva", "Radiologia", "UTI"]}'::jsonb, 149, 'draft');